package id.aldi.life;

import android.app.*; import android.os.*; import android.content.*; import android.graphics.Color; import android.graphics.Typeface; import android.view.*; import android.widget.*; import android.text.*; import java.text.*; import java.util.*;

public class MainActivity extends Activity {
 int ink=Color.rgb(24,29,42), muted=Color.rgb(130,138,153), bg=Color.rgb(246,247,251), accent=Color.rgb(100,82,220);
 LinearLayout root,body,nav; android.content.SharedPreferences prefs; String page="home";
 ArrayList<String> entries=new ArrayList<>();
 public void onCreate(Bundle b){super.onCreate(b); prefs=getSharedPreferences("aldi_life",0); if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7); show("home");}
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
 void show(String p){page=p; root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(bg);setContentView(root);
  LinearLayout top=new LinearLayout(this);top.setPadding(dp(20),dp(22),dp(20),dp(14));top.setOrientation(1); TextView brand=text("ALDI LIFE  ·  YOUR DAILY OS",12,accent);brand.setTypeface(null,1);top.addView(brand); TextView h=text(title(p),28,ink);h.setTypeface(null,1);top.addView(h);root.addView(top);
  ScrollView sc=new ScrollView(this); body=new LinearLayout(this);body.setPadding(dp(18),dp(4),dp(18),dp(24));body.setOrientation(1);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
  if(p.equals("home"))home(); else if(p.equals("money"))money(); else if(p.equals("schedule"))schedule(); else if(p.equals("tasks"))tasks(); else settings();
  nav=new LinearLayout(this);nav.setBackgroundColor(Color.WHITE);nav.setPadding(dp(4),dp(10),dp(4),dp(10));String[][] tabs={{"home","Home"},{"money","Uang"},{"schedule","Jadwal"},{"tasks","Target"},{"settings","Setelan"}};for(String[] a:tabs){TextView t=text(a[1],11,page.equals(a[0])?accent:muted);t.setGravity(17);t.setPadding(0,dp(8),0,dp(8));nav.addView(t,new LinearLayout.LayoutParams(0,-2,1));t.setOnClickListener(v->show(a[0]));}root.addView(nav);
 }
 String title(String p){switch(p){case"money":return"Keuangan";case"schedule":return"Jadwal & alarm";case"tasks":return"Target harian";case"settings":return"Pengaturan";default:return"Hari ini, Aldi.";}}
 void card(String title,String sub){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(16),dp(14),dp(16),dp(14));c.setBackground(round(Color.WHITE,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);body.addView(c,lp);TextView a=text(title,16,ink);a.setTypeface(null,1);c.addView(a);TextView b=text(sub,13,muted);b.setPadding(0,dp(5),0,0);c.addView(b);}
 android.graphics.drawable.GradientDrawable round(int color,int r){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(r));return d;}
 void button(String label,Runnable r){TextView b=text(label,14,Color.WHITE);b.setGravity(17);b.setPadding(dp(14),dp(13),dp(14),dp(13));b.setTypeface(null,1);b.setBackground(round(accent,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);body.addView(b,lp);b.setOnClickListener(v->r.run());}
 EditText field(String hint,int type){EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(14);e.setHint(hint);e.setInputType(type);e.setPadding(dp(12),dp(10),dp(12),dp(10));e.setBackground(round(Color.WHITE,12));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(9);body.addView(e,lp);return e;}
 void home(){String today=new SimpleDateFormat("EEEE, d MMMM yyyy",new Locale("id","ID")).format(new Date());card(today,"Mulai dari satu langkah kecil.");long bal=prefs.getLong("balance",0);card("Saldo tercatat","Rp "+fmt(bal)+"  ·  Perbarui dari menu Keuangan");card("Fokus hari ini",prefs.getString("focus","Belum ada fokus. Tambahkan target harianmu."));card("Pengingat aktif","Jadwalkan alarm dari menu Jadwal.");button("+ Catat transaksi",()->show("money"));button("+ Buat jadwal / alarm",()->show("schedule"));button("+ Tambah target",()->show("tasks"));}
 String fmt(long n){return String.format(Locale("id","ID"),"%,d",n).replace(',','.');}
 void money(){long bal=prefs.getLong("balance",0);card("Saldo berjalan","Rp "+fmt(bal));card("Ringkasan","Pemasukan dan pengeluaran tersimpan di perangkat ini.");EditText amount=field("Nominal (contoh 25000)",2);EditText note=field("Keterangan (gaji, makan, transport...)",1);button("＋ Pemasukan",()->saveMoney(amount,note,true));button("－ Pengeluaran",()->saveMoney(amount,note,false));for(String s:loadList("transactions"))card("Riwayat transaksi",s);}
 void saveMoney(EditText a,EditText n,boolean plus){try{long x=Long.parseLong(a.getText().toString().replace(".","").replace(",",""));long b=prefs.getLong("balance",0)+(plus?x:-x);prefs.edit().putLong("balance",b).apply();addList("transactions",(plus?"+ ":"− ")+"Rp "+fmt(x)+" · "+n.getText().toString()+" · "+new SimpleDateFormat("dd/MM HH:mm").format(new Date()));show("money");}catch(Exception e){a.setError("Masukkan nominal yang benar");}}
 void schedule(){card("Alarm di perangkat","Pengingat memakai notifikasi Android. Izinkan notifikasi dan alarm jika diminta.");EditText title=field("Nama kegiatan (mis. Berangkat kerja)",1);EditText time=field("Jam 24 jam (contoh 07:30)",1);EditText date=field("Tanggal YYYY-MM-DD",1);button("Atur pengingat",()->setAlarm(title.getText().toString(),time.getText().toString(),date.getText().toString()));for(String s:loadList("alarms"))card("Jadwal tersimpan",s);}
 void setAlarm(String name,String tm,String dt){try{String[] t=tm.split(":");String[] d=dt.split("-");Calendar c=Calendar.getInstance();c.set(Integer.parseInt(d[0]),Integer.parseInt(d[1])-1,Integer.parseInt(d[2]),Integer.parseInt(t[0]),Integer.parseInt(t[1]),0);if(c.getTimeInMillis()<=System.currentTimeMillis())throw new Exception();Intent i=new Intent(this,ReminderReceiver.class);i.putExtra("title",name);PendingIntent pi=PendingIntent.getBroadcast(this,(int)(System.currentTimeMillis()%1000000),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)getSystemService(ALARM_SERVICE);if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms()){startActivity(new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM));}am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,c.getTimeInMillis(),pi);addList("alarms",name+" · "+dt+" "+tm);show("schedule");}catch(Exception e){Toast.makeText(this,"Periksa tanggal dan jam. Gunakan format 2026-12-31 dan 07:30.",Toast.LENGTH_LONG).show();}}
 void tasks(){EditText task=field("Apa yang ingin kamu selesaikan?",1);button("＋ Tambah target",()->{String s=task.getText().toString().trim();if(!s.isEmpty()){addList("tasks","□ "+s);prefs.edit().putString("focus",s).apply();show("tasks");}});for(String s:loadList("tasks")){TextView row=text(s+"     ✓",15,ink);row.setPadding(dp(14),dp(14),dp(14),dp(14));row.setBackground(round(Color.WHITE,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);body.addView(row,lp);row.setOnClickListener(v->{addList("done",s);Toast.makeText(this,"Disimpan sebagai selesai",0).show();});}}
 void settings(){card("Privasi","Data transaksi, jadwal, dan target disimpan lokal di HP ini. Belum tersinkron ke cloud.");button("Ekspor cadangan teks",()->{String all="SALDO="+prefs.getLong("balance",0)+"\n"+prefs.getAll().toString();android.content.ClipboardManager cm=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("Aldi Life backup",all));Toast.makeText(this,"Cadangan disalin. Simpan di tempat aman.",Toast.LENGTH_LONG).show();});button("Hapus seluruh data aplikasi",()->new AlertDialog.Builder(this).setTitle("Hapus data?").setMessage("Semua transaksi, target, dan jadwal tersimpan akan dihapus.").setNegativeButton("Batal",null).setPositiveButton("Hapus",(x,y)->{prefs.edit().clear().apply();show("home");}).show());}
 void addList(String k,String s){ArrayList<String> a=loadList(k);a.add(0,s);StringBuilder b=new StringBuilder();for(String x:a)b.append(x.replace("|"," ")).append("|");prefs.edit().putString(k,b.toString()).apply();}
 ArrayList<String> loadList(String k){ArrayList<String>a=new ArrayList<>();String v=prefs.getString(k,"");if(!v.isEmpty())for(String s:v.split("\\|"))if(!s.isEmpty())a.add(s);return a;}
}
